  fallbackActive.value = current ? [current] : []
}

function scrollToSection(id: string) {
  const el = headingEl(id)
  if (!el) return
  if (typeof el.scrollIntoView === 'function') {
    el.scrollIntoView({ behavior: 'smooth', block: 'start' })
  } else {
    window.scrollTo({ top: el.offsetTop, behavior: 'smooth' })
  }
}

onMounted(() => {
  refreshHeadings()
  if (!ioSupported) window.addEventListener('scroll', onScroll, { passive: true })
})
onBeforeUnmount(() => {
  if (!ioSupported) window.removeEventListener('scroll', onScroll)
})

watch(() => store.activeLang, refreshHeadings) // headings text change doesn't matter; skip? not needed
