export type Lang = 'en' | 'id'

export interface LangText {
  en: string
  id: string
}

export interface PersonalInfo {
  name: string
  title: LangText
  phone: string
  email: string
  city: string
  github: string
  linkedin: string
  portfolio: string
}

export interface SkillGroup {
  id: string
  label: LangText
  /** Comma-separated skill list — ATS-safe, no bars/tables. */
  items: LangText
}

export interface ExperienceEntry {
  id: string
  role: LangText
  company: string
  city: string
  /** Format "MM/YYYY". */
  start: string
  /** `null` = still present (renders "Present"/"Sekarang"). */
  end: string | null
  /** 3–5 bullets per role. */
  bullets: LangText[]
  /** Comma-separated stack tags used in this role. */
  stack: string
}

export interface ProjectEntry {
  id: string
  name: string
  url: string
  description: LangText
  stack: string
  impact: LangText
}

export interface EducationEntry {
  id: string
  degree: LangText
  major: LangText
  university: string
  city: string
  year: string
  gpa?: string
}

export interface CertificationEntry {
  id: string
  name: string
  issuer: string
  year: string
}

export interface LanguageEntry {
  id: string
  name: string
  proficiency: LangText
}

export interface ResumeOptions {
  showPhoto: boolean
  educationPosition: 'top' | 'bottom'
}

export interface Resume {
  version: 1
  personal: PersonalInfo
  summary: LangText
  skills: SkillGroup[]
  experience: ExperienceEntry[]
  projects: ProjectEntry[]
  education: EducationEntry[]
  certifications: CertificationEntry[]
  languages: LanguageEntry[]
  options: ResumeOptions
}

export const MAX_SKILL_GROUPS = 4
export const MAX_BULLETS_PER_ROLE = 5

let uidCounter = 0

/** `crypto.randomUUID()` with a counter fallback (jsdom / non-secure contexts). */
export function uid(): string {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID()
  }
  uidCounter += 1
  return `id-${Date.now().toString(36)}-${uidCounter}`
}

export function createLangText(): LangText {
  return { en: '', id: '' }
}

export function createEmptyResume(): Resume {
  return {
