      title: createLangText(),
      phone: '',
      email: '',
      city: '',
      github: '',
      linkedin: '',
      portfolio: '',
    },
    summary: createLangText(),
    skills: [],
    experience: [],
    projects: [],
    education: [],
    certifications: [],
    languages: [],
