import { beforeEach, describe, expect, it } from 'vitest'

import { defineComponent, h } from 'vue'
import { mount } from '@vue/test-utils'
import { useResumeStore } from '@/composables/useResumeStore'
import ResumeFormPanel from '@/components/resume-form/ResumeFormPanel.vue'

/** Minimal nuxt/ui stubs — real components are flaky in jsdom and prop-heavy. */
const UInput = defineComponent({
  name: 'UInput',
  inheritAttrs: false,
  props: { modelValue: { type: null, required: false } },
  emits: ['update:modelValue'],
  setup(props, { emit, attrs }) {
    return () =>
      h('input', {
