import { describe, expect, it } from 'vitest'
import { defineComponent, h, ref } from 'vue'
import { mount } from '@vue/test-utils'
import { writeFileSync } from 'node:fs'
import { Tabs, TabsList, TabsTrigger } from 'reka-ui'

describe('debug reka tabs', () => {
  it('clicks trigger in isolation', async () => {
    const Host = defineComponent({
      setup() {
        const v = ref('en')
        return () =>
          h(Tabs, { modelValue: v.value, 'onUpdate:modelValue': (x: string) => { v.value = x } }, {
            default: () => [
              h(TabsList, null, {
                default: () => [
                  h(TabsTrigger, { value: 'en' }, { default: () => 'EN' }),
                  h(TabsTrigger, { value: 'id' }, { default: () => 'ID' }),
                ],
              }),
            ],
          })
      },
    })

    const wrapper = mount(Host)
    const idTab = wrapper.findAll('button[role="tab"]').find((tab) => tab.text() === 'ID')!
    let stateBefore = idTab.attributes('data-state')
    idTab.element.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, button: 0 }))
    await wrapper.vm.$nextTick()
    const idTabAfter = wrapper.findAll('button[role="tab"]').find((tab) => tab.text() === 'ID')!
    writeFileSync('/tmp/reka-debug.json', JSON.stringify({
      stateBefore,
      stateAfter: idTabAfter.attributes('data-state'),
      selectedText: wrapper.findAll('button[aria-selected="true"]').map((b) => b.text()),
    }))
    expect(true).toBe(true)
  })
})
